        internal static int Get(int codePoint)
        {
            if ((uint)codePoint < 128u)
                return Ascii[codePoint];
            int low = 0;
            int high = Ranges.Length / 3 - 1;
            while (low <= high)
            {
                int middle = (low + high) >> 1;
                int offset = middle * 3;
                if (codePoint < Ranges[offset])
                    high = middle - 1;
                else if (codePoint > Ranges[offset + 1])
                    low = middle + 1;
                else
                    return Ranges[offset + 2];
            }
            return 0;
        }
    }
